// ── Solveur : copie fidèle de createSim() de 3d.html (sans le décodage de scène) ──
// Intègre le latent scalaire z : z̈ = −dE/dz − barrière − γ·ż − β·sign(ż) + α·f,
// avec E(z)=‖φ(z)−φ(z_rest)‖² (MLP φ appris), RK4 (DT=rk4_dt), pas fixe à physics_dt
// cadencé par timeScale, et plafond d'énergie α=effortGate sur l'effort extérieur.
function createRockingSim(meta) {
    meta = meta || ROCKING_META;
    const { phi, gamma: GAMMA_LEARNED, beta: BETA_LEARNED } = meta;
    const Z_MIN = meta.z_min, Z_MAX = meta.z_max;
    const H = phi.b0.length;

    // Poids φ aplatis : w0 (H,1), w2 (H,H) en row-major.
    const w0 = Float32Array.from(phi.w0.map((r) => r[0]));
    const b0 = Float32Array.from(phi.b0);
    const w2 = new Float32Array(H * H);
    for (let i = 0; i < H; i++) for (let j = 0; j < H; j++) w2[i * H + j] = phi.w2[i][j];
    const b2 = Float32Array.from(phi.b2);

    const elu = (x) => (x > 0 ? x : Math.expm1(x));
    const dElu = (x) => (x > 0 ? 1 : Math.exp(x));
    const softplus = (x) => (x > 20 ? x : Math.log1p(Math.exp(Math.max(x, -500))));
    const sigmoid = (x) => 1 / (1 + Math.exp(-x));

    // φ(z) et dφ/dz en une passe.
    const _h1 = new Float32Array(H), _d1 = new Float32Array(H);
    const _h2 = new Float32Array(H), _d2 = new Float32Array(H);
    function phiFwd(z, out, dout) {
        for (let i = 0; i < H; i++) {
            const a = w0[i] * z + b0[i];
            _h1[i] = elu(a);
            if (dout) _d1[i] = dElu(a) * w0[i];
        }
        for (let i = 0; i < H; i++) {
            let a = b2[i], da = 0;
            const row = i * H;
            for (let j = 0; j < H; j++) {
                a += w2[row + j] * _h1[j];
                if (dout) da += w2[row + j] * _d1[j];
            }
            out[i] = elu(a);
            if (dout) dout[i] = dElu(a) * da;
        }
    }

    const _phiRest = new Float32Array(H);
    phiFwd(phi.z_rest, _phiRest, null);

    // E(z) = ‖φ(z) − φ(z_rest)‖²
    function energy(z) {
        phiFwd(z, _h2, null);
        let e = 0;
        for (let i = 0; i < H; i++) { const d = _h2[i] - _phiRest[i]; e += d * d; }
        return e;
    }
    // dE/dz = 2 Σ_i (φ_i(z) − φ_i(z_rest)) · dφ_i/dz
    function dEdz(z) {
        phiFwd(z, _h2, _d2);
        let g = 0;
        for (let i = 0; i < H; i++) g += (_h2[i] - _phiRest[i]) * _d2[i];
        return 2 * g;
    }

    function barrierGrad(z, W, k) {
        return W * k * (sigmoid(k * (z - Z_MAX)) - sigmoid(k * (Z_MIN - z)));
    }

    const st = {
        z: meta.z0, v: meta.v0 ?? 0, step: 0,
        f_ext: 0, gamma: GAMMA_LEARNED, W: meta.w_default, k: meta.k_default,
        timeScale: meta.time_scale_default,   // secondes simulées par seconde réelle
        acc: 0,                               // accumulateur temps réel
    };

    // Plafond d'énergie sur l'effort (cf. 3d.html) : l'effort extérieur ne peut pas
    // pousser l'énergie mécanique au-dessus de son seuil initial E_MAX ; il reste
    // pleinement réactif partout ailleurs. Ne modifie pas la dynamique libre.
    const E_MAX = energy(meta.z0) + 0.5 * (meta.v0 ?? 0) * (meta.v0 ?? 0);
    const E_GATE = 0.15 * E_MAX + 1e-6;
    const V_GATE = 0.05;
    function effortGate(z, v, f) {
        if (f === 0) return 1;
        const Emech = energy(z) + 0.5 * v * v;
        const gE = 0.5 * (1 + Math.tanh((Emech - E_MAX) / E_GATE));
        const sP = 0.5 * (1 + Math.tanh((f * v / Math.abs(f)) / V_GATE));
        return 1 - gE * sP;
    }

    function accel(z, v, gammaScale) {
        let a = -dEdz(z) - barrierGrad(z, st.W, st.k);
        a -= GAMMA_LEARNED * gammaScale * v;
        const vNorm = Math.max(Math.abs(v), 1e-6);
        a -= BETA_LEARNED * gammaScale * v / vNorm;
        const f = st.f_ext;
        a += effortGate(z, v, f) * f;
        return a;
    }

    const DT = meta.rk4_dt;
    function rk4Step() {
        const gs = GAMMA_LEARNED > 0 ? st.gamma / GAMMA_LEARNED : 1.0;
        const z = st.z, v = st.v;
        const k1v = accel(z, v, gs), k1z = v;
        const k2v = accel(z + 0.5 * DT * k1z, v + 0.5 * DT * k1v, gs), k2z = v + 0.5 * DT * k1v;
        const k3v = accel(z + 0.5 * DT * k2z, v + 0.5 * DT * k2v, gs), k3z = v + 0.5 * DT * k2v;
        const k4v = accel(z + DT * k3z, v + DT * k3v, gs), k4z = v + DT * k3v;
        st.z = z + (DT / 6) * (k1z + 2 * k2z + 2 * k3z + k4z);
        st.v = v + (DT / 6) * (k1v + 2 * k2v + 2 * k3v + k4v);
        st.step++;
    }

    // Avance la physique en pas fixes (physics_dt) cadencés par timeScale, découplés
    // de la fréquence d'affichage. Le clamp évite un rattrapage explosif après un gel.
    function tick(dtWall) {
        st.acc += Math.min(dtWall * st.timeScale, 0.5);
        let n = 0;
        while (st.acc >= meta.physics_dt && n < 10) { rk4Step(); st.acc -= meta.physics_dt; n++; }
        return n;
    }

    function reset() {
        st.z = meta.z0; st.v = meta.v0 ?? 0; st.step = 0;
        st.f_ext = 0; st.acc = 0;
    }

    return {
        state: st, meta,
        Z_MIN, Z_MAX, z0: meta.z0, v0: meta.v0 ?? 0,
        energy, dEdz, tick, reset,
        setForce(f) { st.f_ext = f; },
        clearForce() { st.f_ext = 0; },
        setDamping(g) { st.gamma = g; },
        setTimeScale(ts) { st.timeScale = ts; },
        setZ(z, v) { st.z = z; st.v = (v === undefined ? 0 : v); st.acc = 0; },
    };
}

if (typeof window !== 'undefined') {
    window.createRockingSim = createRockingSim;
    window.ROCKING_META = ROCKING_META;
}
